    @property
    def run_root(self) -> Path:
        return self.base.run_root

    def start(self) -> dict[str, Any]:
        return self.base.start()

    def analyze_capture(self, capture: ClinicCaptureInput) -> dict[str, Any]:
        started = time.perf_counter()
        rgb = capture.channel("RGB_M").path
        manifest = self.base.analyze(rgb, sample_id=capture.capture_alias)
        sample_root = self.run_root / "repeat_1" / capture.capture_alias
