        merged = self.base._write_canonical_indexes(
            sample_root=sample_root,
            image_path=rgb,
            items=items,
            responses=responses,
            wall_seconds=time.perf_counter() - started,
            route="clinic_four_light",
            input_images=input_images,
        )
        merged["采集别名"] = capture.capture_alias
        merged["来源组"] = capture.source_group_alias
        merged["固定数据ManifestSHA256"] = capture.fixture_manifest_sha256
        merged["签名权威ManifestSHA256"] = capture.signed_manifest_sha256
        merged["通道状态"] = receipt["registration"]
        (sample_root / "manifest.json").write_text(
            json.dumps(json_safe(merged), ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return merged

    def close(self) -> None:
        self.base.close()


