        for service in ("acne", "wrinkle"):
            spec = self.manifest[service]
            keys = set(spec["raw_result_oss_keys"]) | set(
                spec["raw_result_structured_keys"]
            )
            with self.subTest(service=service):
                self._assert_legacy_and_extended(service, keys)

