def _prune_metric_groups(groups: Any, allowed: frozenset[str]) -> dict[str, Any]:
    if not isinstance(groups, dict): return {}
    output: dict[str, Any] = {}
    for level_name in ("core_metrics", "auxiliary_metrics"):
        level = groups.get(level_name)
        if not isinstance(level, dict): continue
        dimensions: dict[str, Any] = {}
        for dimension, metrics in level.items():
            if not isinstance(metrics, dict): continue
            if dimension == "analysis_scope":
                identity = {key: metrics[key] for key in ("analysis_region", "evaluation_status", "valid_skin_area_px") if key in metrics}
                if identity: dimensions[dimension] = identity
                continue
            selected = {key: value for key, value in metrics.items() if key in allowed}
            if selected: dimensions[dimension] = selected
        if dimensions: output[level_name] = dimensions
    return output


def _prune_regions(rows: Any, project: str) -> list[dict[str, Any]]:
    if not isinstance(rows, list): return []
    allowed = INCREMENTAL_REGION_METRICS.get(project, frozenset())
    output = []
    for row in rows:
        if not isinstance(row, dict): continue
        selected = {key: row[key] for key in ("analysis_region", "evaluation_status", "valid_skin_area_px") if key in row}
        selected.update(_prune_metric_groups(row, allowed))
        metric_groups = {level: {dimension: metrics for dimension, metrics in selected.get(level, {}).items() if dimension != "analysis_scope"} for level in ("core_metrics", "auxiliary_metrics")}
        if any(groups for groups in metric_groups.values()): output.append(selected)
    return output


def to_incremental_document(document: dict[str, Any], project: str | None = None) -> dict[str, Any]:
    public = document if is_english_document(document) else to_english_document(document)
    key = project or _PROJECT_VALUE_TO_KEY.get(str(public.get("project") or ""), str(public.get("project") or ""))
    overall = public.get("overall_metrics", {})
    if key == "purple":
        incremental_overall = {sub: _prune_metric_groups(overall.get(sub, {}), INCREMENTAL_OVERALL_METRICS[f"purple_{sub}"]) for sub in ("uv_spots", "porphyrin")}
        incremental_regions = []
        for index, group in enumerate(public.get("region_metrics", [])):
            sub = "uv_spots" if index == 0 else "porphyrin"
            regions = _prune_regions(group.get("region_metrics", []), f"purple_{sub}") if isinstance(group, dict) else []
            if regions: incremental_regions.append({"subproject": sub, "regions": regions})
        left_right = {}
    else:
        allowed = INCREMENTAL_OVERALL_METRICS.get(key)
        if allowed is None: raise ValueError(f"未知医学 V2 项目: {key!r}")
        incremental_overall = _prune_metric_groups(overall, allowed)
        incremental_regions = _prune_regions(public.get("region_metrics", []), key)
        raw_laterality = public.get("left_right_comparison", {})
        allowed_laterality = INCREMENTAL_LATERALITY_METRICS.get(key, frozenset())
        left_right = {name: value for name, value in raw_laterality.items() if name in allowed_laterality} if isinstance(raw_laterality, dict) else {}
    result = {"metrics_version": public.get("metrics_version", "medical_metrics_v2_20260728"), "scoring_status": public.get("scoring_status", "uncalibrated"), "units": public.get("imaging_and_units", {}), "overall_metrics": incremental_overall, "region_metrics": incremental_regions, "left_right_comparison": left_right, "medical_limitations": list(public.get("medical_limitations") or [])}
    _assert_no_chinese_keys(result)
    return result
