class ClinicTwelveAnalysisOrchestrator:
    """Reuse the established RGB services, then replace clinic-only heads."""

    def __init__(self, output_root: Path, cuda_device: str = "0", *, stage_input: bool = False) -> None:
        self.base = TwelveAnalysisOrchestrator(
            output_root,
            cuda_device=cuda_device,
            stage_input=stage_input,
        )
        self.provider = ClinicFourLightProvider()

    @property
    def run_id(self) -> str:
        return self.base.run_id

    @property
    def run_root(self) -> Path:
        return self.base.run_root

    def start(self) -> dict[str, Any]:
        return self.base.start()

    def analyze_capture(self, capture: ClinicCaptureInput) -> dict[str, Any]:
        started = time.perf_counter()
        rgb = capture.channel("RGB_M").path
        manifest = self.base.analyze(rgb, sample_id=capture.capture_alias)
        sample_root = self.run_root / "repeat_1" / capture.capture_alias
        replacements, receipt = self.provider.run(
            capture,
            sample_root / "clinic_modality",
        )
        items = dict(manifest["十二项结果"])
        items.update(replacements)
        responses = dict(manifest.get("服务原始响应") or {})
        responses["clinic_modality"] = {
            "status": "success",
            "seconds": receipt["timing_seconds"]["clinic_modality_total"],
            "result": {"metadata": receipt},
        }
        input_images = {channel.role: str(channel.path) for channel in capture.channels}
        merged = self.base._write_canonical_indexes(
            sample_root=sample_root,
            image_path=rgb,
            items=items,
            responses=responses,
            wall_seconds=time.perf_counter() - started,
            route="clinic_four_light",
            input_images=input_images,
        )
        merged["采集别名"] = capture.capture_alias
        merged["来源组"] = capture.source_group_alias
        merged["固定数据ManifestSHA256"] = capture.fixture_manifest_sha256
        merged["签名权威ManifestSHA256"] = capture.signed_manifest_sha256
        merged["通道状态"] = receipt["registration"]
        merged["红棕底图生成回执"] = receipt["red_brown_provider"]
        (sample_root / "manifest.json").write_text(
            json.dumps(json_safe(merged), ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return merged

    def close(self) -> None:
        self.base.close()


