            "毛囊定位表现": (f"{prefix}P50单体面积（像素）",),
        }
    features = {group: _numeric(overall, names) for group, names in definitions.items()}
    count = _number(overall.get(f"{prefix}特征数量（个）"))
    if count is not None:
        features["instance_count"] = int(count)
    return _pick(overall, *keys), features


