def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument(
        "--evidence-root",
        type=Path,
        default=EVIDENCE_ROOT,
        help="existing bounded Fast3 run below test-output/doctor-v2",
    )
    parser.add_argument("--capture", action="append", choices=CAPTURES)
    parser.add_argument(
        "--instrument-style-root",
        type=Path,
        help="bounded root containing one passed right-side re-detection directory per capture",
    )
    parser.add_argument(
        "--vascular-root",
        type=Path,
        help="bounded VascularStructure-V3-Clinic run root",
    )
    args = parser.parse_args()
    captures = tuple(args.capture or CAPTURES)
    source_evidence_root = args.evidence_root.resolve(strict=True)
    allowed_root = (PROJECT_ROOT / "test-output/doctor-v2").resolve(strict=True)
    if not source_evidence_root.is_relative_to(allowed_root):
        raise ValueError("evidence root must remain below test-output/doctor-v2")
    instrument_style_root = None
    if args.instrument_style_root is not None:
        instrument_style_root = args.instrument_style_root.resolve(strict=True)
        if not instrument_style_root.is_relative_to(allowed_root):
            raise ValueError("instrument-style root must remain below test-output/doctor-v2")
    vascular_root = None
    if args.vascular_root is not None:
        vascular_root = args.vascular_root.resolve(strict=True)
        if not vascular_root.is_relative_to(allowed_root):
            raise ValueError("vascular root must remain below test-output/doctor-v2")
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    rows = [
        generate_capture(
            alias,
            output,
            source_evidence_root,
            instrument_style_root,
            vascular_root,
        )
        for alias in captures
    ]
    manifest = {
